import{_ as d}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o,X as a}from"./chunks/vendor-vueuse.XPft87tp.js";const m=JSON.parse('{"title":"MySQL 存储引擎","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/mysql-storage-engine.md","filePath":"mysql/mysql-storage-engine.md","lastUpdated":1786990830000}'),n={name:"mysql/mysql-storage-engine.md"};function r(l,t,i,s,h,p){return o(),e("div",null,t[0]||(t[0]=[a('<h1 id="mysql-存储引擎" tabindex="-1">MySQL 存储引擎 <a class="header-anchor" href="#mysql-存储引擎" aria-label="Permalink to &quot;MySQL 存储引擎&quot;">​</a></h1><h3 id="innodb-为什么是默认选择" tabindex="-1">InnoDB 为什么是默认选择 <a class="header-anchor" href="#innodb-为什么是默认选择" aria-label="Permalink to &quot;InnoDB 为什么是默认选择&quot;">​</a></h3><p>从 MySQL 5.5 起，InnoDB 就是默认存储引擎，也是业务表几乎唯一需要认真对待的引擎。它同时提供事务、行级锁、MVCC、崩溃恢复和外键，写并发和宕机恢复都建立在 redo / undo 之上。</p><p>MyISAM 曾是 5.1 之前的默认引擎，只有表级锁、没有事务，崩溃后修复能力弱。现在偶尔还能在只读统计、某些临时结果里见到，生产业务表已经没有再选它的理由。</p><p>「InnoDB 查询一定比 MyISAM 慢」是过时结论。当前版本里 InnoDB 读路径并不弱，Buffer Pool 可以把热点页留在内存；真正拉开差距的是并发更新和崩溃恢复，这两项 MyISAM 补不上。</p><h3 id="innodb-与-myisam-对比" tabindex="-1">InnoDB 与 MyISAM 对比 <a class="header-anchor" href="#innodb-与-myisam-对比" aria-label="Permalink to &quot;InnoDB 与 MyISAM 对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>InnoDB</th><th>MyISAM</th></tr></thead><tbody><tr><td>事务</td><td>支持</td><td>不支持</td></tr><tr><td>行级锁</td><td>支持</td><td>主要是表级锁</td></tr><tr><td>MVCC</td><td>支持</td><td>不支持</td></tr><tr><td>崩溃恢复</td><td>redo + undo</td><td>能力较弱</td></tr><tr><td>外键</td><td>支持</td><td>不支持</td></tr><tr><td>并发更新</td><td>高</td><td>低</td></tr><tr><td>索引形态</td><td>聚簇索引，主键叶子节点存整行</td><td>非聚簇索引，叶子节点存行地址</td></tr><tr><td>文件</td><td>MySQL 8.0 每表一个 <code>.ibd</code>（数据 + 索引）</td><td><code>.MYD</code> 数据 + <code>.MYI</code> 索引</td></tr><tr><td>使用场景</td><td>业务系统、需要事务和并发写</td><td>读多、对事务要求低；现在很少用</td></tr></tbody></table><p>InnoDB 的表数据按主键顺序排在聚簇索引里。主键选得乱，插入就会在页中间打洞，引发页分裂。MyISAM 数据和索引分开，主键和二级索引都只存行指针，这一点和 InnoDB 的二级索引「叶子存主键、再回表」不一样。</p><h3 id="buffer-pool-与其他引擎" tabindex="-1">Buffer Pool 与其他引擎 <a class="header-anchor" href="#buffer-pool-与其他引擎" aria-label="Permalink to &quot;Buffer Pool 与其他引擎&quot;">​</a></h3><p>InnoDB 把数据页、索引页缓存在 Buffer Pool 里，改动先写内存和 redo，再择机刷盘。Change Buffer 用来合并二级索引的写，自适应哈希索引则是引擎在 Buffer Pool 里自动建的等值加速结构，不能当成「给 InnoDB 表手写 HASH 索引」。</p><p>MEMORY 引擎整表放内存，适合生命周期很短的中间结果，进程退出或宕机数据就没了。磁盘临时表在 MySQL 8.0 里也不再依赖 MyISAM，而是 TempTable / InnoDB。</p><p>选引擎时默认 InnoDB 即可。为了「读更快」把业务表改成 MyISAM，会同时丢掉事务、行锁和可靠恢复，这个交换现在不成立。</p>',12)]))}const y=d(n,[["render",r]]);export{m as __pageData,y as default};
